#include <cstddef>
#include <memory>
#include <string>
#include <utility>
#include <vector>

struct Player
{
    std::string name{};
    int level{ 1 };
};

std::unique_ptr<Player> makePlayer(std::string name, int level)
{
    return std::make_unique<Player>(Player{ std::move(name), level });
}

class Team
{
public:
    void add(std::unique_ptr<Player> player) { m_players.push_back(std::move(player)); }
    std::size_t size() const { return m_players.size(); }
    const Player& at(std::size_t index) const { return *m_players[index]; }

    int totalLevel() const
    {
        int total{ 0 };
        for (const auto& player : m_players)
        {
            total += player->level;
        }
        return total;
    }

private:
    std::vector<std::unique_ptr<Player>> m_players{};
};

unitTests:
TEST("makePlayer") { const auto p{ makePlayer("Aria", 7) }; CHECK(p != nullptr); if (p) { CHECK_EQ(p->name, "Aria"); CHECK_EQ(p->level, 7); } }
TEST("the team takes ownership") { Team t{}; auto p{ makePlayer("Bo", 3) }; t.add(std::move(p)); CHECK(p == nullptr); CHECK_EQ(t.size(), 1u); CHECK_EQ(t.at(0).name, "Bo"); }
TEST("totalLevel") { Team t{}; t.add(makePlayer("a", 2)); t.add(makePlayer("b", 5)); t.add(makePlayer("c", 10)); CHECK_EQ(t.totalLevel(), 17); CHECK_EQ(Team{}.totalLevel(), 0); }
TEST("everything is freed automatically") { CHECK_NO_LEAK(Team t{}; for (int i{ 0 }; i < 20; ++i) t.add(makePlayer("someone with quite a long name", i))); }

